import http.server, socketserver, json, os, sys

ROOT = sys.argv[1]
PORT = int(sys.argv[2])

# Minimal PNG logo (1x1 transparent) as data URL fallback
class H(http.server.SimpleHTTPRequestHandler):
    def __init__(self, *a, **kw):
        super().__init__(*a, directory=ROOT, **kw)

    def log_message(self, *a):
        pass

    def do_POST(self):
        if self.path.endswith('/portal/appLogin/apps'):
            body = json.dumps({
                "code": 200,
                "msg": "ok",
                "data": [
                    {"appId": "a1", "appName": "物业管理", "appLogo": "", "authorized": True},
                    {"appId": "a2", "appName": "物业掌通", "appLogo": "", "authorized": True},
                ],
            }).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.send_header("Access-Control-Allow-Origin", "*")
            self.end_headers()
            self.wfile.write(body)
            return
        return super().do_POST()

    def do_GET(self):
        if self.path.startswith('/api/'):
            body = json.dumps({"code": 200, "msg": "ok", "data": []}).encode("utf-8")
            self.send_response(200)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)
            return
        return super().do_GET()

class Server(socketserver.ThreadingTCPServer):
    allow_reuse_address = True

with Server(("127.0.0.1", PORT), H) as httpd:
    print("SERVING", ROOT, "ON", PORT, flush=True)
    httpd.serve_forever()
